/// <summary>
/// CB705_Rebate batch jobs & Vendor payback extension
/// </summary>
[ExtensionOf(tablestr(TAMRebateTable))]
final class METTAMRebateTable_Extension
{
}

Method.Source:
/// <summary>
/// CB705_Rebate batch jobs & Vendor payback extension
/// </summary>
/// <returns>Check customer deal type validation</returns>
public boolean validateWrite()
{
    boolean ret = next validateWrite();

    if (ret)
    {
        TAMRebateDeal rebateDeal = TAMRebateDeal::find(this.RebateDeal);

        if (rebateDeal.ModuleInventCustVend == ModuleInventCustVend::Cust
        &&  rebateDeal.RebateReconciliation == TAMRebateReconciliation::Deal
        &&  this.METSkipPosting)
        {
            ret = checkFailed("@MET:ManualRebatePostingValidation");
        }

        // CB705_VendorRebatePosting
        if (rebateDeal.ModuleInventCustVend == ModuleInventCustVend::Vend
        &&  rebateDeal.METInvoiceConsolidationByRebateType
        &&  !this.METVendRebateTypeId)
        {
            ret = checkFailed(strFmt("@RebatesAndDeductions:FieldMustBeSpecified", fieldPName(TAMRebateTable, METVendRebateTypeId)));
        }

        // Add validation for reconcile by line, the TAMRebateTable.RebatePostingId becomes mandatory.
        if (rebateDeal.RebateReconciliation == TAMRebateReconciliation::Line
        &&  this.RebatePostingId == '')
        {
            ret = checkFailed(strFmt("@RebatesAndDeductions:FieldMustBeSpecified", fieldPName(TAMRebateTable, RebatePostingId)));
        }
        // Bug 284448: CB705 - Vendor Claims external data source does not link the transaction to METExternalSellData table
        // Add validation Transaction type must be "External sales data" when the deal has Use external sales data
        if (rebateDeal.METUseExternalSellData
        &&  this.SourceType != TAMRebateSourceType::METExternalSalesData)
        {
            ret = checkFailed(strFmt("@MET:RebateTableSourceTypeValidation", fieldPName(TAMRebateTable, SourceType)));
        }

        // Bug 294020: CB705- Batch extension for rabate- Manual rebate posting validation is not working for vendor rebate deal
        if (this.ModuleInventCustVend == ModuleInventCustVend::Vend
        &&  this.METVendRebateTypeId)
        {
            TAMRebateTable rebateTableValidation;
            select firstonly rebateTableValidation
                       where rebateTableValidation.RebateDeal == this.RebateDeal
                          && rebateTableValidation.RebateId != this.RebateId
                          && rebateTableValidation.METVendRebateTypeId == this.METVendRebateTypeId
                          && rebateTableValidation.METSkipPosting != this.METSkipPosting;

            if (rebateTableValidation)
            {
                ret = checkFailed(strFmt("@MET:RebateSkipPostingValidation", this.METVendRebateTypeId));
            }
        }

        ret = this.metValidateVolumetric(rebateDeal) && ret;
    }
    return ret;
}

/// <summary>
/// Validate the rebate lines for a rebate deal.
/// </summary>
/// <returns></returns>
public boolean metValidateVolumetric(TAMRebateDeal _rebateDeal)
{
    boolean ret = true;

    if (_rebateDeal.METVolumetricTierDeal == NoYes::Yes)
    {
        TAMRebateTable rebateTableLoc;

        select count(RecId) from rebateTableLoc
            where rebateTableLoc.RebateDeal == this.RebateDeal;

        if (rebateTableLoc.RecId > 2)
        {
            ret = checkFailed("@MET:METVolumetricValidation");
        }

        select firstonly METTierLineType, RecId from rebateTableLoc
            where rebateTableLoc.RebateDeal == this.RebateDeal
            && rebateTableLoc.RecId != this.RecId;

        if (rebateTableLoc.RecId && this.RecId != rebateTableLoc.RecId && rebateTableLoc.METTierLineType == this.METTierLineType)
        {
            ret = checkFailed("@MET:NoSimilarLineType");
        }
    }
    return ret;
}

/// <summary>
/// Get price attribute header details
/// </summary>
/// <returns>Price attribute header details</returns>
[SysClientCacheDataMethodAttribute(true)]
public display GUPPricingAttributeDetailsPreview metPricingAttributeDetailsHeader()
{
    GUPPricingAttributeDetailsPreview       retVal;

    retVal = this.pricingAttributeDetailsHeader();

    if (retVal != METConstants::emptyString)
    {
        retVal = this.getRebateConditionalVal(retVal);

        if (retVal == METConstants::emptyString)
        {
            retVal = METConstants::PriceAttributeHeader;
        }
    }
    else
    {
        retVal = METConstants::emptyString;
    }

    return retVal;
}

/// <summary>
/// Get price attribute line details
/// </summary>
/// <returns>Price attribute line details</returns>
[SysClientCacheDataMethodAttribute(true)]
public display GUPPricingAttributeDetailsPreview metPricingAttributeDetailsLine()
{
    GUPPricingAttributeDetailsPreview   retVal;

    retVal = this.pricingAttributeDetailsLine();

    if (retVal != METConstants::emptyString)
    {
        retVal = this.getRebateConditionalVal(retVal);

        if (retVal == METConstants::emptyString)
        {
            retVal = METConstants::PriceAttributeLine;
        }
    }
    else
    {
        retVal = METConstants::emptyString;
    }

    return retVal;
}

/// <summary>
/// Get rebate conditional value
/// </summary>
/// <param name = "_value">Value</param>
/// <returns>GUPPricingAttributeDetailsPreview</returns>
public GUPPricingAttributeDetailsPreview getRebateConditionalVal(GUPPricingAttributeDetailsPreview _value)
{
    GUPPricingAttributeDetailsPreview displayDetailsRetVal;

    container conDisplayDet = str2con(_value, METConstants::Semicolon);

    for (int i=1; i<=conLen(conDisplayDet); i++)
    {
        str       conStrVal              = conPeek(conDisplayDet, i);
        container conDisplayDetCondValue = str2con(conStrVal, METConstants::colon);

        if (conLen(conDisplayDetCondValue) == 2 &&
            strRTrim(conPeek(conDisplayDetCondValue, 2)) != METConstants::emptyString)
        {
            displayDetailsRetVal += strFmt(METConstants::DisplayCondVal, conStrVal);
        }
    }

    return strLRTrim(displayDetailsRetVal);
}

/// <summary>
/// While insert the <c>TAMRebateTable</c> record update pricing rule header information.
/// </summary>
public void insert()
{
    if (this.TAMRebateDeal().METVolumetricTierDeal == NoYes::Yes)
    {
        TAMRebateTable tamRebateTable;

        if (this.METTierLineType == METTierLineType::Value)
        {
            select firstonly PricingRuleHeader, PriceComponentCombination from tamRebateTable
                where tamRebateTable.METTierLineType == METTierLineType::Rate
                && tamRebateTable.RebateDeal == this.RebateDeal;

            if (tamRebateTable.PricingRuleHeader)
            {
                this.PricingRuleHeader = tamRebateTable.PricingRuleHeader;
                this.PriceComponentCombination = tamRebateTable.PriceComponentCombination;
            }
        }
        else
        {
            select firstonly forupdate tamRebateTable
                where tamRebateTable.METTierLineType == METTierLineType::Value
                && tamRebateTable.RebateDeal == this.RebateDeal;

            if (tamRebateTable.RecId)
            {
                ttsbegin;
                tamRebateTable.PriceComponentCombination = this.PriceComponentCombination;
                tamRebateTable.PricingRuleHeader = this.PricingRuleHeader;
                tamRebateTable.doUpdate();
                ttscommit;
            }
        }
    }

    next insert();

}

/// <summary>
/// While update the <c>TAMRebateTable</c> record update pricing rule header information.
/// </summary>
public void update()
{
    TAMRebateTable tamRebateTable;

    if (this.TAMRebateDeal().METVolumetricTierDeal == NoYes::Yes)
    {
        if (this.METTierLineType == METTierLineType::Rate)
        {
            select firstonly forupdate tamRebateTable
                where tamRebateTable.METTierLineType == METTierLineType::Value
                && tamRebateTable.RebateDeal == this.RebateDeal;

            if (tamRebateTable.RecId)
            {
                ttsbegin;
                tamRebateTable.PricingRuleHeader = this.PricingRuleHeader;
                tamRebateTable.PriceComponentCombination = this.PriceComponentCombination;
                tamRebateTable.doUpdate();
                ttscommit;
            }
        }
        else
        {
            select firstonly PricingRuleHeader, PriceComponentCombination from tamRebateTable
                where tamRebateTable.METTierLineType == METTierLineType::Rate
                && tamRebateTable.RebateDeal == this.RebateDeal;

            if (tamRebateTable.PricingRuleHeader)
            {
                this.PricingRuleHeader = tamRebateTable.PricingRuleHeader;
                this.PriceComponentCombination = tamRebateTable.PriceComponentCombination;
            }
        }
    }

    next update();

}

/// <summary>
/// Checks whether tier line type rebate table lines exist
/// </summary>
/// <param name = "_rebateDeal">Rebate deal recId</param>
/// <param name = "_tierLineType">Tier line type</param>
/// <returns>True or false</returns>
static boolean existByTierType(TAMRebateDealRecId  _rebateDeal, METTierLineType _tierLineType)
{
    return (select firstonly RecId from tamRebateTable
            where tamRebateTable.RebateDeal == _rebateDeal
            && tamRebateTable.METTierLineType == _tierLineType).RecId != 0;
}
